/* 代码7-6 方案二：使用 ::after 伪元素（推荐） */
.clr::after{
    content:"";
    display:block;
    clear:right;
}

/* 举一反三：清除其他方向或两侧浮动，
   只需修改 clear 的属性值即可 */

/* 配合的 HTML */
